    [370+Math.sin(t*0.38+4)*95, 55+Math.cos(t*0.85+2)*75, 0.065, 2.8, 1.05],
    [240+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.52)*85, 0.085, 2.0, 0.95],
